import type { BetterAuthPlugin } from "better-auth";
import { createAuthMiddleware, getOAuthState } from "better-auth/api";
import { signJWT } from "better-auth/plugins/jwt";
import { Hono } from "hono";
import { Pkce } from "./lib/pkce";

// The Runable API derives allowed deep-link targets from this — re-exported here because the API
// consumes the broker as raw source.
export { applicationScheme } from "./lib/scheme";

export type ManagedProvider = "google" | "apple" | "microsoft";

export interface ManagedAuthOriginCheck {
  applicationId: string;
  origin: string;
}

const DEFAULT_PROVIDERS: readonly ManagedProvider[] = ["google", "apple", "microsoft"];
const CLIENT_IP_HEADERS = ["cf-connecting-ip", "x-forwarded-for"] as const;

// Forward the real client IP to the internal social sign-in so rate limiting / risk checks see the
// end user, not the broker.
const forwardClientIp = (base: Record<string, string>, request: Request) => {
  const headers = new Headers(base);
  for (const name of CLIENT_IP_HEADERS) {
    const value = request.headers.get(name);
    if (value) headers.set(name, value);
  }
  return headers;
};

// Better Auth returns the next hop either as a 302 `location` or as `{ url }` / `{ redirect_uri }` JSON.
const redirectLocation = async (response: Response) => {
  const location = response.headers.get("location");
  if (location) return location;
  const data = await response
    .clone()
    .json()
    .catch(() => null);
  const body = data as { url?: string; redirect_uri?: string } | null;
  return body?.url ?? body?.redirect_uri ?? null;
};

// Redirect to `location` while preserving the upstream response's headers (notably any `set-cookie`
// the social sign-in sets for the OAuth state) — a bare 302 would drop them.
const redirectPreservingHeaders = (location: string, source: Response) => {
  const headers = new Headers(source.headers);
  headers.set("location", location);
  return new Response(source.body, { status: 302, headers });
};

// App-bound fragment redirect: delivers the token (or a provider error) to the validated redirect
// target in the URL fragment, never a query param. Undefined fields are omitted. http(s) targets
// are validated as bare origins, so delivery is pinned to the origin root; custom-scheme deep links
// (native/desktop) keep their full path — Expo Go routes through it (`exp://host/--/…`).
const managedFragmentRedirect = (target: string, fragment: Record<string, string | undefined>) => {
  const params = new URLSearchParams();
  for (const [key, value] of Object.entries(fragment)) {
    if (value !== undefined) params.set(key, value);
  }
  const url = new URL(target);
  const destination =
    url.protocol === "http:" || url.protocol === "https:" ? new URL("/", target) : url;
  destination.hash = params.toString();
  return new Response(null, { status: 302, headers: { location: destination.toString() } });
};

const stateString = (state: Record<string, unknown> | undefined, key: string) =>
  typeof state?.[key] === "string" ? (state[key] as string) : undefined;

interface ProviderErrorFragmentInput {
  location: string | null | undefined;
  baseURL: string;
  nonce: string;
}

// A provider error (e.g. ?error=access_denied) lands in the callback's redirect Location. Extract it
// as an app-bound fragment so the app/popup can surface it; returns undefined when there is no error.
const providerErrorFragment = ({ location, baseURL, nonce }: ProviderErrorFragmentInput) => {
  const errorUrl = location ? new URL(location, baseURL) : undefined;
  const error = errorUrl?.searchParams.get("error");
  if (!error) return undefined;
  return {
    error,
    error_description: errorUrl?.searchParams.get("error_description") ?? undefined,
    nonce,
  };
};

export interface ManagedAuthBrokerPluginOptions {
  /** The broker's public base URL, e.g. `https://api.runable.com`. The minted JWT's `iss` derives from it. */
  apiUrl: string;
  /**
   * Re-validates the delivery origin against the application record. The callback hook is reachable
   * via a direct `/sign-in/social` with crafted `additionalData`, so the origin is checked here too —
   * not only at `/start` — before any token is minted or delivered.
   */
  isOriginAllowed: (check: ManagedAuthOriginCheck) => Promise<boolean>;
  /** Minted-JWT lifetime in seconds. Default 300 — it only bootstraps the app's own session. */
  tokenTtlSeconds?: number;
}

/**
 * Better Auth plugin that mints the managed-auth JWT inside the authenticated social callback. The
 * provider callback only runs after the authorization code validates against the provider, so it IS
 * the proof of provider auth — there is no separate `/finish` route and nothing to replay.
 *
 * `/start` drives `/sign-in/social` with `{ applicationId, origin, nonce, codeChallenge? }` carried in
 * `additionalData` (DB-backed OAuth state). This after-hook recovers them via `getOAuthState()`, reads the just-created
 * session user, mints a short `aud`-scoped JWT, and replaces the callback's redirect with one to the
 * app's own origin (token in the fragment). Provider cancellation/errors are forwarded the same way.
 */
export const managedAuthBrokerPlugin = ({
  apiUrl,
  isOriginAllowed,
  tokenTtlSeconds = 300,
}: ManagedAuthBrokerPluginOptions): BetterAuthPlugin => {
  const issuer = new URL("/api/auth", apiUrl).toString();
  return {
    id: "runable-managed-auth-broker",
    hooks: {
      after: [
        {
          matcher: (context) => context.path?.startsWith("/callback/") ?? false,
          handler: createAuthMiddleware(async (c) => {
            const rawState = await getOAuthState();
            const state = rawState as Record<string, unknown> | undefined;
            const applicationId = stateString(state, "applicationId");
            const origin = stateString(state, "origin");
            const nonce = stateString(state, "nonce");
            const codeChallenge = stateString(state, "codeChallenge");
            // Not a managed-auth flow — leave the normal callback redirect intact.
            if (!applicationId || !origin || !nonce) return;
            // Re-validate the origin here too (this hook is reachable via a direct /sign-in/social with
            // crafted additionalData): never mint or deliver to an origin the app doesn't own.
            if (!(await isOriginAllowed({ applicationId, origin }))) return;

            const location = c.context.responseHeaders?.get("location");
            // This redirect is app-bound and cross-site — never leak the broker session cookie onto it.
            c.context.responseHeaders = new Headers();

            const errorFragment = providerErrorFragment({
              location,
              baseURL: c.context.baseURL,
              nonce,
            });
            if (errorFragment) {
              c.context.returned = managedFragmentRedirect(origin, errorFragment);
              return;
            }

            const user = c.context.newSession?.user;
            if (!user) {
              c.context.returned = managedFragmentRedirect(origin, { error: "no_session", nonce });
              return;
            }

            const issuedAt = Math.floor(Date.now() / 1000);
            // Sign with Better Auth's own jwt keypair (read from the adapter — the same key the
            // broker's JWKS serves), so the app verifies it offline. aud/sub/iss/exp/jti are taken
            // straight from the payload.
            const token = await signJWT(c, {
              payload: {
                sub: user.id,
                email: user.email,
                email_verified: user.emailVerified ?? false,
                name: user.name ?? undefined,
                picture: user.image ?? undefined,
                aud: applicationId,
                iss: issuer,
                iat: issuedAt,
                exp: issuedAt + tokenTtlSeconds,
                jti: crypto.randomUUID(),
                // Native/desktop legs send a PKCE challenge; the app's exchange then requires the
                // matching verifier, so an intercepted deep-link fragment alone can't be redeemed.
                ...(codeChallenge ? { [Pkce.CLAIM]: codeChallenge } : {}),
              },
            });
            c.context.returned = managedFragmentRedirect(origin, { token, nonce });
          }),
        },
      ],
    },
  };
};

export interface CreateManagedAuthStartOptions {
  /** The broker's public base URL, e.g. `https://api.runable.com`. */
  apiUrl: string;
  /** Forwards a request to the broker's Better Auth handler (used to drive `/sign-in/social`). */
  handler: (request: Request) => Promise<Response>;
  /**
   * Is `origin` currently routed to the app `applicationId`? The broker's application record is the
   * source of truth (preview always; subdomain + custom domain once published), so this read replaces
   * per-origin redirect-URI registration.
   */
  isOriginAllowed: (check: ManagedAuthOriginCheck) => Promise<boolean>;
  /** Header that bypasses captcha on the internal `/sign-in/social` call (the broker sets it server-side). */
  captchaBypassHeader: string;
  /** Allowed providers. Defaults to google/apple/microsoft. */
  providers?: readonly ManagedProvider[];
}

/**
 * The `/start` entry point: validate the app origin, then drive the provider, carrying the app
 * context in `additionalData`. Mounted by the Runable API at `/auth/managed`. Pairs with
 * `managedAuthBrokerPlugin`, which finishes the flow inside the social callback.
 */
export const createManagedAuthStart = ({
  apiUrl,
  handler,
  isOriginAllowed,
  captchaBypassHeader,
  providers = DEFAULT_PROVIDERS,
}: CreateManagedAuthStartOptions) => {
  // A fixed, broker-trusted callback target. The after-hook replaces the response before it renders,
  // so `/landing` only needs to exist as a trusted origin for Better Auth's callbackURL check.
  const landingUrl = new URL("/api/auth/managed/landing", apiUrl).toString();

  return new Hono()
    .get("/start", async (c) => {
      const provider = c.req.query("provider");
      const applicationId = c.req.query("application_id");
      const origin = c.req.query("origin");
      const nonce = c.req.query("nonce");
      // Optional S256 challenge from native/desktop clients; rides the OAuth state into the JWT.
      const codeChallenge = c.req.query("code_challenge");
      if (!provider || !providers.includes(provider as ManagedProvider)) {
        return c.json({ message: "Unsupported managed auth provider" }, 400);
      }
      if (!applicationId || !origin || !nonce) {
        return c.json({ message: "Missing application_id, origin, or nonce" }, 400);
      }
      if (!(await isOriginAllowed({ applicationId, origin }))) {
        return c.json({ message: "Unrecognized managed auth origin" }, 400);
      }

      const headers = forwardClientIp(
        { accept: "application/json", "content-type": "application/json" },
        c.req.raw,
      );
      headers.set(captchaBypassHeader, "1");

      const response = await handler(
        new Request(new URL("/api/auth/sign-in/social", apiUrl).toString(), {
          method: "POST",
          headers,
          body: JSON.stringify({
            provider,
            callbackURL: landingUrl,
            newUserCallbackURL: landingUrl,
            errorCallbackURL: landingUrl,
            // The app context rides in the DB-backed OAuth state and is recovered in the callback hook.
            additionalData: {
              applicationId,
              origin,
              nonce,
              ...(codeChallenge ? { codeChallenge } : {}),
            },
          }),
        }),
      );
      const location = await redirectLocation(response);
      if (!location) return response;
      // Preserve any state set-cookie on the first hop to the provider.
      return redirectPreservingHeaders(location, response);
    })
    .get("/landing", (c) => c.body(null, 204));
};
